-- Primer piloto SECURITY para migrar legada 22: SOLO CANDIDATA
BEGIN;
DO $batch$
DECLARE p jsonb; res jsonb; ev jsonb; hp text; before_legacy jsonb; before_core jsonb; before_dep jsonb; ekb_count int;
BEGIN
SELECT jsonb_agg(to_jsonb(r) ORDER BY id) INTO before_legacy FROM lf_ops.reglas r;
SELECT jsonb_agg(to_jsonb(r) ORDER BY codigo) INTO before_core FROM lf_ops.nucleo_reglas r;
SELECT jsonb_agg(to_jsonb(r) ORDER BY regla,version) INTO before_dep FROM lf_ops.nucleo_deprecaciones r;
SELECT count(*) INTO ekb_count FROM public.lf_error_knowledge;
IF (SELECT count(*) FROM lf_ops.nucleo_reglas WHERE estado='VIGENTE')<>57 OR (SELECT count(*) FROM lf_ops.nucleo_reglas WHERE estado='CANDIDATA')<>1 OR EXISTS(SELECT 1 FROM lf_ops.nucleo_reglas WHERE codigo='S1-C01') OR (SELECT count(*) FROM lf_ops.nucleo_deprecaciones)<>0 THEN RAISE EXCEPTION 'S1_BASELINE_DRIFT'; END IF;
INSERT INTO lf_ops.nucleo_hechos(codigo,tipo_dato,unidad,descripcion) VALUES('s1_intento_persistir_otp','boolean','ninguna','Hecho lógico de intento de persistir OTP en backend; binding físico no acreditado.');
INSERT INTO lf_ops.nucleo_familia_vocabulario(familia,hecho,origen) VALUES('SECURITY','s1_intento_persistir_otp','CURADO');
INSERT INTO lf_ops.nucleo_hechos(codigo,tipo_dato,unidad,descripcion) VALUES('s1_entorno_produccion','boolean','ninguna','El entorno del intento es producción, determinado en backend; sin binding físico acreditado.');
INSERT INTO lf_ops.nucleo_familia_vocabulario(familia,hecho,origen) VALUES('SECURITY','s1_entorno_produccion','CURADO');
INSERT INTO lf_ops.nucleo_hechos(codigo,tipo_dato,unidad,descripcion) VALUES('s1_otp_sin_hash_antes_persistir','boolean','ninguna','El OTP a persistir no tiene hash antes de la escritura; no se asume fuente física.');
INSERT INTO lf_ops.nucleo_familia_vocabulario(familia,hecho,origen) VALUES('SECURITY','s1_otp_sin_hash_antes_persistir','CURADO');
p:='{"tipo":"NUEVA","codigo":"S1-C01","clave":"s1_otp_persistencia_hash_produccion","familia":"SECURITY","naturaleza":"CONDUCTA","clase":"BACKEND","alcance":"BACKEND","modo":"HEREDA","dueno":"TECNICO","titulo":"Bloquear intento de persistir OTP sin hash en producción","descripcion":"BLOQUEAR solo un intento efectivo de persistir OTP cuando el entorno sea producción y el OTP a persistir carezca de hash. Esos son los tres únicos hechos booleanos evaluados; no bloquea por mera lectura, ni en sandbox o prototipo por esta regla. No afirma controles físicos ni binding runtime de Paulo.","condicion":{"op":"y","izq":{"op":"y","izq":{"op":"=","izq":{"hecho":"s1_intento_persistir_otp"},"der":{"lit":true}},"der":{"op":"=","izq":{"hecho":"s1_entorno_produccion"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"s1_otp_sin_hash_antes_persistir"},"der":{"lit":true}}},"efecto":"BLOQUEAR","autoridad":"LEG-TECNICO","impacto":"REVISAR","origen":{"tipo":"MIGRACION","ref":"lf_ops.reglas/22","solicitante":"Cristhian 2026-11-23"},"pruebas":[{"casuistica":"SE_CUMPLE","entrada":{"s1_intento_persistir_otp":true,"s1_entorno_produccion":true,"s1_otp_sin_hash_antes_persistir":true},"esperado":true},{"casuistica":"NO_SE_CUMPLE","entrada":{"s1_intento_persistir_otp":true,"s1_entorno_produccion":true,"s1_otp_sin_hash_antes_persistir":false},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"s1_intento_persistir_otp":true,"s1_entorno_produccion":false,"s1_otp_sin_hash_antes_persistir":true},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"s1_intento_persistir_otp":false,"s1_entorno_produccion":true,"s1_otp_sin_hash_antes_persistir":true},"esperado":false},{"casuistica":"SE_CUMPLE","entrada":{"s1_intento_persistir_otp":true,"s1_entorno_produccion":true,"s1_otp_sin_hash_antes_persistir":true},"esperado":true},{"casuistica":"NO_SE_CUMPLE","entrada":{"s1_intento_persistir_otp":false,"s1_entorno_produccion":false,"s1_otp_sin_hash_antes_persistir":true},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"s1_intento_persistir_otp":true,"s1_entorno_produccion":true,"s1_otp_sin_hash_antes_persistir":false},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"s1_intento_persistir_otp":true,"s1_entorno_produccion":false,"s1_otp_sin_hash_antes_persistir":false},"esperado":false}]}'::jsonb;
res:=lf_ops.nucleo_regla_proponer_v1(p,false);
IF res->>'resultado'<>'EVALUADA_SIN_ESCRIBIR' OR (res->>'bloqueantes')::int<>0 THEN RAISE EXCEPTION 'S1_PREFLIGHT %',res; END IF;
res:=lf_ops.nucleo_regla_proponer_v1(p,true);
IF res->>'resultado'<>'CANDIDATA' OR (res->>'version')::int<>1 THEN RAISE EXCEPTION 'S1_WRITE %',res; END IF;
IF (SELECT count(*) FROM lf_ops.nucleo_regla_pruebas WHERE regla='S1-C01' AND version=1)<>8 THEN RAISE EXCEPTION 'S1_8_TESTS'; END IF;
IF lf_ops.nucleo_eval_v1((SELECT condicion FROM lf_ops.nucleo_regla_versiones WHERE regla='S1-C01' AND version=1),'{"s1_intento_persistir_otp":false,"s1_entorno_produccion":true,"s1_otp_sin_hash_antes_persistir":true}'::jsonb) IS DISTINCT FROM 'false'::jsonb THEN RAISE EXCEPTION 'S1_INTENT_MUTANT'; END IF;
ev:=lf_ops.nucleo_regla_evaluar_v1('S1-C01',true);
IF ev->>'decision'='AUTO' THEN RAISE EXCEPTION 'S1_NO_UNJUDGED_AUTO'; END IF;
hp:=lf_ops.nucleo_hash_paquete_v1('S1-C01',1);
RAISE NOTICE 'S1_RESULT %',jsonb_build_object('regla','S1-C01','version',1,'hash_version',(SELECT hash FROM lf_ops.nucleo_regla_versiones WHERE regla='S1-C01' AND version=1),'hash_paquete',hp,'nota',ev->'nota','decision',ev->>'decision','pruebas',8,'promocion','NO_PROMOVIDA');
INSERT INTO public.lf_error_knowledge(codigo,categoria,titulo,descripcion,causa_raiz,patron,prevencion,validacion,severidad,frecuencia,primera_vez,ultima_vez,lote_origen,estado,evidencia) VALUES('LF-NUCLEO-586-INVENTARIO-SECURITY-PILOTO-20261123-001','NUCLEO_REGLAS','Inventario 586 y primer piloto SECURITY','586 legadas etiquetadas sin inferir cobertura por origen; S1-C01 candidata de OTP sin hash en producción.','La columna regla_legacy_id está NULL en 58; origen.ref no certifica cobertura.','NUCLEO_COBERTURA_NO_INFERIDA','Requiere puente N:M de cobertura validada; no promocionar S1-C01 sin juicio Claude.','PG17 8 casos y negativo de intento, BEGIN/ROLLBACK, núcleo 17/17, IG 14/14.','MEDIUM',1,now(),now(),'INVENTARIO-SECURITY-20261123','ACTIVO','docs/nucleo/LF_AGRUPACION_586_LEGADAS_20261123.md; docs/nucleo/LF_INVENTARIO_586_LEGADAS_20261123.csv; docs/nucleo/LF_SECURITY_S1C01_CASOS_20261123.md');
IF (SELECT jsonb_agg(to_jsonb(r) ORDER BY id) FROM lf_ops.reglas r) IS DISTINCT FROM before_legacy OR (SELECT jsonb_agg(to_jsonb(r) ORDER BY codigo) FROM lf_ops.nucleo_reglas r WHERE codigo<>'S1-C01') IS DISTINCT FROM before_core OR (SELECT jsonb_agg(to_jsonb(r) ORDER BY regla,version) FROM lf_ops.nucleo_deprecaciones r) IS DISTINCT FROM before_dep OR (SELECT count(*) FROM public.lf_error_knowledge)<>ekb_count+1 OR (SELECT count(*) FROM lf_ops.nucleo_reglas WHERE estado='VIGENTE')<>57 THEN RAISE EXCEPTION 'S1_UNAUTHORIZED_DRIFT'; END IF;
RAISE NOTICE 'S1_PASS 8/8 candidate only';
END $batch$;
COMMIT;
